    opener.open('https://github.com', timeout=5)
    out['without_proxy'] = 'UNEXPECTED_ALLOWED'
except Exception as error:
    out['without_proxy'] = str(error)
try:
    socket.create_connection(('1.1.1.1',443), timeout=3).close()
